from solution import choose_num
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# --- explicit examples from spec ---

def test_example_12_15_is_14():
    assert choose_num(12, 15) == 14


def test_example_13_12_is_minus_one():
    assert choose_num(13, 12) == -1


# --- reference model ---

def reference(x, y):
    """Obviously correct brute-force model of spec."""
    if x > y:
        return -1
    best = -1
    for n in range(x, y + 1):
        if n % 2 == 0:
            if n > best:
                best = n
    return best


# --- properties ---

@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_result_matches_reference_model(x, y):
    assert choose_num(x, y) == reference(x, y)


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_result_is_minus_one_or_even_in_range(x, y):
    r = choose_num(x, y)
    assert r == -1 or (r % 2 == 0 and x <= r <= y)


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_result_is_maximal_even(x, y):
    r = choose_num(x, y)
    if r != -1:
        # no larger even fits in range: r+2 must exceed y
        assert r + 2 > y
        # r+1 (odd) may still be <= y, but r+2 must not be
        assert r + 2 > y or r + 2 < x  # second disjunct impossible when r in range, kept for clarity


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_minus_one_iff_no_even_in_range(x, y):
    r = choose_num(x, y)
    has_even = any(n % 2 == 0 for n in range(x, y + 1)) if x <= y else False
    assert (r == -1) == (not has_even)


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_x_greater_than_y_returns_minus_one(x, y):
    assume(x > y)
    assert choose_num(x, y) == -1


@given(st.integers(min_value=1, max_value=1000))
def test_singleton_even_returns_itself(x):
    assume(x % 2 == 0)
    assert choose_num(x, x) == x


@given(st.integers(min_value=1, max_value=1000))
def test_singleton_odd_returns_minus_one(x):
    assume(x % 2 == 1)
    assert choose_num(x, x) == -1


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_y_even_and_x_le_y_implies_result_is_y(x, y):
    assume(x <= y and y % 2 == 0)
    assert choose_num(x, y) == y


@given(st.integers(min_value=1, max_value=999), st.integers(min_value=1, max_value=1000))
def test_y_odd_result_is_y_minus_one_or_minus_one(x, y):
    assume(x <= y and y % 2 == 1)
    if x == y:
        assert choose_num(x, y) == -1
    else:
        # y-1 is even and >= x, so it must be the answer
        assert choose_num(x, y) == y - 1


@given(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000))
def test_widening_range_never_decreases_answer(x, y):
    # metamorphic: extending y upward cannot make answer smaller (or stay -1 then jump)
    assume(x <= y)
    r1 = choose_num(x, y)
    r2 = choose_num(x, y + 2)
    if r1 == -1:
        assert r2 != -1  # interval of length >=2 extended by 2 must contain an even
    else:
        assert r2 >= r1


def test_boundary_smallest_inputs():
    assert choose_num(1, 1) == -1
    assert choose_num(2, 2) == 2
    assert choose_num(1, 2) == 2
    assert choose_num(1, 3) == 2
    assert choose_num(2, 3) == 2
    assert choose_num(3, 3) == -1
    assert choose_num(3, 4) == 4
    assert choose_num(3, 5) == 4


def test_boundary_adjacent_pairs():
    # touching intervals of size 2 always contain exactly one even
    assert choose_num(3, 4) == 4
    assert choose_num(4, 5) == 4
    assert choose_num(5, 6) == 6
    assert choose_num(7, 8) == 8


def test_large_values():
    assert choose_num(1000, 1000) == 1000
    assert choose_num(999, 999) == -1
    assert choose_num(999, 1000) == 1000
    assert choose_num(999, 1001) == 1000
    assert choose_num(1001, 1002) == 1002
